import 'package:flutter/material.dart';
import '../app.dart';

class PostureCaptureScreen extends StatefulWidget { const PostureCaptureScreen({super.key}); @override State<PostureCaptureScreen> createState()=>_PostureCaptureScreenState(); }
class _PostureCaptureScreenState extends State<PostureCaptureScreen>{ final organizationId=TextEditingController(); final memberId=TextEditingController(); String result=''; @override Widget build(BuildContext context){ final api=AppScope.of(context).api; return Scaffold(appBar: AppBar(title: const Text('AI Posture Capture')), body: ListView(padding: const EdgeInsets.all(16), children:[TextField(controller: organizationId, decoration: const InputDecoration(labelText:'Organization ID')), TextField(controller: memberId, decoration: const InputDecoration(labelText:'Member ID')), const SizedBox(height:16), FilledButton(onPressed:() async { final response=await api.post('/posture/analyze-frame', {'organizationId':organizationId.text,'memberId':memberId.text,'exerciseType':'squat','landmarks':[{'name':'left_hip','x':0,'y':0,'visibility':1},{'name':'left_knee','x':0,'y':1,'visibility':1},{'name':'left_ankle','x':1,'y':1,'visibility':1}]}); setState(()=>result=response.toString()); }, child: const Text('Analyze Demo Frame')), Text(result)])); }}
